69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
76	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
77	     * addresses are lower-cased before being stored.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
81	
82	    /** An owner's postcode, when supplied, must be exactly four digits. */
83	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
84	
85	    /**
86	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
87	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
94	     * named logger keeps them addressable independently of the class's diagnostic logging.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Maximum number of owners a single city may contain. A create that would take the owner's city
100	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
101	     */
102	    private static final int CITY_OWNER_LIMIT = 50;
103	
104	    /**
105	     * Maximum number of owners that may be registered on a single day. A create that would take the
106	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
107	     * have already been created that day - is rejected with a 429.
108	     */
109	    private static final int DAILY_OWNER_LIMIT = 100;
110	
111	    /**
112	     * Number of owners that must already have been created for a given day before the create
113	     * response flags a bulk sign-up. When more than this many owners already share a
114	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
115	     */
116	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
117	
118	    /**
119	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
120	     * like a weekend and rolled forward to the next non-holiday business day.
121	     */
122	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
123	        LocalDate.of(2026, 1, 1),
124	        LocalDate.of(2026, 1, 26),
125	        LocalDate.of(2026, 4, 25),
126	        LocalDate.of(2026, 12, 25),
127	        LocalDate.of(2026, 12, 28));
128	
129	    /**
130	     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
131	     * already seen, the originally created owner is returned instead of creating a duplicate.
132	     */
133	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
134	
135	    private final ClinicService clinicService;
136	
137	    private final OwnerMapper ownerMapper;
138	
139	    private final PetMapper petMapper;
140	
141	    private final VisitMapper visitMapper;
142	
143	    private final HttpServletRequest request;
144	
145	    /**
146	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
147	     * create with an already-seen key returns the originally created owner rather than a duplicate.
148	     */
149	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
150	
151	    public OwnerRestControllerV1(ClinicService clinicService,
152	                                 OwnerMapper ownerMapper,
153	                                 PetMapper petMapper,
154	                                 VisitMapper visitMapper,
155	                                 HttpServletRequest request) {
156	        this.clinicService = clinicService;
157	        this.ownerMapper = ownerMapper;
158	        this.petMapper = petMapper;
159	        this.visitMapper = visitMapper;
160	        this.request = request;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
166	        Collection<Owner> owners;
167	        if (lastName != null) {
168	            owners = this.clinicService.findOwnerByLastName(lastName);
169	        } else {
170	            owners = this.clinicService.findAllOwners();
171	        }
172	        if (owners.isEmpty()) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
187	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
188	    }
189	
190	    /**
191	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
192	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
193	     * owner sign-ups.
194	     *
195	     * @param registrationDate the day to inspect, or {@code null}
196	     * @return {@code true} when more than the threshold of owners are registered on that day
197	     */
198	    private boolean isBulkSignupDay(LocalDate registrationDate) {
199	        return registrationDate != null
200	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
206	        String idempotencyKey = idempotencyKey();
207	        if (idempotencyKey != null) {
208	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
209	            if (existing != null) {
210	                return new ResponseEntity<>(existing, HttpStatus.OK);
211	            }
212	        }
213	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
214	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
215	        finalizeOwnerForCreate(owner);
216	        this.clinicService.saveOwner(owner);
217	        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
218	        if (idempotencyKey != null) {
219	            this.idempotencyStore.put(idempotencyKey, response.getBody());
220	        }
221	        return response;
222	    }
223	
224	    /**
225	     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
226	     * when the header is absent or blank.
227	     */
228	    private String idempotencyKey() {
229	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
230	        return StringUtils.hasText(key) ? key : null;
231	    }
232	
233	    /**
234	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
235	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
236	     * submitted address is canonicalized, the required fields and the optional postcode and
237	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
238	     * registration date is defaulted to the server date when absent and rolled forward to a business
239	     * day. The household id and identity key are derived; a create that would join an already-populated
240	     * household is rejected unless it opts in with {@code sharesHousehold}, and otherwise a soft-match
241	     * duplicate is flagged.
242	     *
243	     * @param ownerFieldsDto the submitted owner fields
244	     * @return the normalized owner, not yet persisted
245	     */
246	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
247	        resolveAddressFields(ownerFieldsDto);
248	        validateRequiredFields(ownerFieldsDto);
249	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
250	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
251	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
252	        owner.setEmail(normalizeEmail(owner.getEmail()));
253	        validateRegistrationDate(owner.getRegistrationDate());
254	        if (owner.getRegistrationDate() == null) {
255	            owner.setRegistrationDate(LocalDate.now());
256	        }
257	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
258	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
259	        resolveHouseholdIdentity(owner, sharesHousehold);
260	        return owner;
261	    }
262	
263	    /**
264	     * Places the owner about to be created into its household and settles its identity against the
265	     * owners already on file. The owner's {@code householdId} is derived deterministically from its
266	     * last name and postcode and its {@code identityKey} is composed from that household and the
267	     * normalized contact details. Unless the request opted into a shared household, an owner whose
268	     * identity key exactly matches an existing household member is rejected with a 409; and, again only
269	     * when the household was not opted into, a soft-match against an existing owner flags the new owner
270	     * as a possible duplicate. Distinct people sharing a household are admitted, with their membership
271	     * level later capped by {@link #applyMembershipLevelCap(Owner)}.
272	     *
273	     * @param owner the normalized owner about to be created, with its contact details already normalized
274	     * @param sharesHousehold whether the request opted into joining an existing household
275	     */
276	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
277	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
278	        owner.setIdentityKey(buildIdentityKey(owner));
279	        if (!sharesHousehold) {
280	            rejectHouseholdDuplicate(owner);
281	        }
282	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
283	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
284	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
285	    }
286	
287	    /**
288	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
289	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
290	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
291	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
292	     * registration date, measured before it is saved, which the caller uses to decide the response's
293	     * {@code bulkSignupWarning}.
294	     *
295	     * @param owner the normalized owner about to be created
296	     * @return the number of owners already registered on the owner's registration date
297	     */
298	    private long enforceCreateLimits(Owner owner) {
299	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
300	            throw new OwnerCityFullException(owner.getCity());
301	        }
302	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
303	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
304	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
305	        }
306	        return ownersRegisteredOnDay;
307	    }
308	
309	    /**
310	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
311	     * de-duplicated customer code, the number of existing namesakes, the household size once the
312	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
313	     *
314	     * @param owner the normalized owner about to be created
315	     */
316	    private void finalizeOwnerForCreate(Owner owner) {
317	        owner.setCustomerCode(buildCustomerCode(owner));
318	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
319	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
320	        applyMembershipLevelCap(owner);
321	    }
322	
323	    /**
324	     * Caps the membership level of an owner about to be created so it cannot exceed one above the
325	     * current maximum membership level among the owner's existing household members. The owner is not
326	     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
327	     * file; each member's effective (already-capped) level is read via
328	     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
329	     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
330	     * its fully-derived level.
331	     *
332	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
333	     */
334	    private void applyMembershipLevelCap(Owner owner) {
335	        activeHouseholdMembers(owner.getHouseholdId()).stream()
336	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
337	            .max()
338	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
339	    }
340	
341	    /**
342	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
343	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
344	     * count, and adds the {@code Location} header pointing at the new owner.
345	     *
346	     * @param owner the owner that has just been saved, with its generated id populated
347	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
348	     * @return the created-owner response
349	     */
350	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
351	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
352	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
353	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
354	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
355	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
356	        HttpHeaders headers = new HttpHeaders();
357	        headers.setLocation(UriComponentsBuilder.newInstance()
358	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
359	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
360	    }
361	
362	    /**
363	     * Canonicalizes the submitted address fields into the form that is validated, stored and
364	     * returned, before any required-field check or mapping runs. This is the single place a create
365	     * request's address input is resolved.
366	     *
367	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
368	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
369	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
370	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
371	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
372	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
373	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
374	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
375	     * that is blank only after normalization is left blank here and rejected later by
376	     * {@link #validateRequiredFields}.
377	     *
378	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
379	     */
380	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
381	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
382	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
383	        if (!line1.isEmpty()) {
384	            ownerFieldsDto.setAddressLine1(line1);
385	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
386	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
387	        }
388	        else {
389	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
390	        }
391	    }
392	
393	    /**
394	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
395	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
396	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
397	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
398	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
399	     * normalization is still rejected.
400	     *
401	     * @param ownerFieldsDto the submitted owner fields
402	     */
403	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
404	        List<String> missingFields = new ArrayList<>();
405	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
406	            missingFields.add("firstName");
407	        }
408	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
409	            missingFields.add("lastName");
410	        }
411	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
412	            missingFields.add("address");
413	        }
414	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
415	            missingFields.add("city");
416	        }
417	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
418	            missingFields.add("telephone");
419	        }
420	        if (!missingFields.isEmpty()) {
421	            throw new MissingOwnerFieldsException(missingFields);
422	        }
423	    }
424	
425	    /**
426	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
427	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
428	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
429	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
430	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
431	     * whose {@code errors} array lists {@code postcode}.
432	     *
433	     * @param postcode the submitted postcode, or {@code null} when none was supplied
434	     * @param city the owner's city, whose region determines the acceptable postcode range
435	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
436	     */
437	    private void validatePostcode(String postcode, String city) {
438	        if (!StringUtils.hasText(postcode)) {
439	            return;
440	        }
441	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
442	            throw new InvalidOwnerFieldsException(List.of("postcode"));
443	        }
444	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
445	            throw new InvalidOwnerFieldsException(List.of("postcode"));
446	        }
447	    }
448	
449	    /**
450	     * Validates an owner's optional registration date. Registration date is optional, so a missing
451	     * value is accepted (the create later defaults it to the server date). When a value is supplied
452	     * it may not lie in the future: a date later than the server's current date is rejected with a
453	     * 400 whose {@code errors} array lists {@code registrationDate}.
454	     *
455	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
456	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
457	     */
458	    private void validateRegistrationDate(LocalDate registrationDate) {
459	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
460	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
461	        }
462	    }
463	
464	    /**
465	     * Rejects a submitted owner whose derived {@code identityKey} exactly matches that of an existing
466	     * member of the same household - the same normalized telephone, email and household, which marks
467	     * the same person being entered twice. Distinct people who merely share a household (a different
468	     * telephone or email) are not duplicates: they are admitted so the household can hold more than one
469	     * member, with the joiner's membership level capped by {@link #applyMembershipLevelCap(Owner)}. A
470	     * genuine identity collision is reported to the client as a 409 Conflict. A request may knowingly
471	     * bypass this check by opting in with {@code sharesHousehold}, in which case it is not performed.
472	     *
473	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
474	     */
475	    private void rejectHouseholdDuplicate(Owner owner) {
476	        boolean identityInUse = activeHouseholdMembers(owner.getHouseholdId()).stream()
477	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
478	        if (identityInUse) {
479	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
480	        }
481	    }
482	
483	    /**
484	     * Returns the owners that currently belong to the household identified by {@code householdId} -
485	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
486	     * because they no longer count as present members, so this is the household as it stands for the
487	     * owner being created. This is the single lookup of a household's current members behind the
488	     * household checks that reason about who is already there.
489	     *
490	     * @param householdId the derived household identifier to look up
491	     * @return the existing, non-deleted owners sharing that household, in no particular order
492	     */
493	    private List<Owner> activeHouseholdMembers(String householdId) {
494	        return this.clinicService.findAllOwners().stream()
495	            .filter(existing -> !existing.isDeleted())
496	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
497	            .collect(Collectors.toList());
498	    }
499	
500	    /**
501	     * Derives the owner's {@code identityKey}, formatted
502	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
503	     * and email have already been normalized. The household segment always carries the owner's
504	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
505	     * the same household automatically.
506	     *
507	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
508	     * @return the derived identity key
509	     */
510	    private String buildIdentityKey(Owner owner) {
511	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
512	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
513	    }
514	
515	    /**
516	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
517	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
518	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
519	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
520	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
521	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
522	     * postcode was supplied, since both owners must share one; when several existing owners match, the
523	     * earliest (lowest id) is used.
524	     *
525	     * @param owner the normalized owner about to be created, with its telephone already normalized
526	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
527	     */
528	    private Integer findPossibleDuplicate(Owner owner) {
529	        if (!StringUtils.hasText(owner.getPostcode())) {
530	            return null;
531	        }
532	        return this.clinicService.findAllOwners().stream()
533	            .filter(existing -> !existing.isDeleted())
534	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
535	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
536	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
537	            .map(Owner::getId)
538	            .filter(id -> id != null)
539	            .min(Integer::compareTo)
540	            .orElse(null);
541	    }
542	
543	    /**
544	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
545	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
546	     * address; the accepted value is lower-cased before it is stored and returned.
547	     *
548	     * @param email the raw email value submitted by the client, or {@code null}
549	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
550	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
551	     */
552	    private String normalizeEmail(String email) {
553	        if (!StringUtils.hasText(email)) {
554	            return email;
555	        }
556	        if (!EMAIL_PATTERN.matcher(email).matches()) {
557	            throw new InvalidOwnerFieldsException(List.of("email"));
558	        }
559	        String normalized = email.toLowerCase();
560	        String domain = normalized.substring(normalized.indexOf('@') + 1);
561	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
562	            throw new InvalidOwnerFieldsException(List.of("email"));
563	        }
564	        return normalized;
565	    }
566	
567	    /**
568	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
569	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
570	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
571	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
572	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
573	     *
574	     * @param owner the normalized owner about to be created
575	     * @return the assigned, de-duplicated customer code
576	     */
577	    private String buildCustomerCode(Owner owner) {
578	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
579	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
580	        return deduplicateCustomerCode(code);
581	    }
582	
583	    /**
584	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
585	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
586	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
587	     *
588	     * @param code the composed customer code, before de-duplication
589	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
590	     */
591	    private String deduplicateCustomerCode(String code) {
592	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
593	            .map(Owner::getCustomerCode)
594	            .filter(existing -> existing != null)
595	            .collect(Collectors.toSet());
596	        if (!existingCodes.contains(code)) {
597	            return code;
598	        }
599	        int suffix = 2;
600	        while (existingCodes.contains(code + "-" + suffix)) {
601	            suffix++;
602	        }
603	        return code + "-" + suffix;
604	    }
605	
606	    /**
607	     * Counts how many owners already exist that share the supplied first and last name, compared
608	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
609	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
610	     *
611	     * @param firstName the submitted owner's first name
612	     * @param lastName the submitted owner's last name
613	     * @return the number of existing owners with the same first and last name, ignoring case
614	     */
615	    private int countNamesakes(String firstName, String lastName) {
616	        return (int) this.clinicService.findAllOwners().stream()
617	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
618	                && lastName.equalsIgnoreCase(existing.getLastName()))
619	            .count();
620	    }
621	
622	    /**
623	     * Counts how many existing owners already belong to the supplied household, identified by its
624	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
625	     * owner is added (this count plus one).
626	     *
627	     * @param householdId the normalized household identifier of the owner being created
628	     * @return the number of existing owners already sharing that {@code householdId}
629	     */
630	    private int countHouseholdMembers(String householdId) {
631	        return (int) this.clinicService.findAllOwners().stream()
632	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
633	            .count();
634	    }
635	
636	    /**
637	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
638	     * enforce the per-city capacity limit when a new owner is created.
639	     *
640	     * @param city the submitted owner's city
641	     * @return the number of existing owners in that city, ignoring case
642	     */
643	    private long countOwnersInCity(String city) {
644	        return this.clinicService.findAllOwners().stream()
645	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
646	            .count();
647	    }
648	
649	    /**
650	     * Counts how many owners have already been created on the supplied registration date. Used to
651	     * enforce the per-day capacity limit when a new owner is created.
652	     *
653	     * @param registrationDate the registration date of the owner being created
654	     * @return the number of existing owners already registered on that date
655	     */
656	    /**
657	     * Rolls a registration date forward to a business day. A registration date must fall on a
658	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
659	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
660	     * returned unchanged. Every value derived from the registration date (such as the membership
661	     * number's year segment) and the daily create-limit therefore use the adjusted date.
662	     *
663	     * @param date the effective registration date, whether supplied or defaulted to the server date
664	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
665	     */
666	    private LocalDate toBusinessDay(LocalDate date) {
667	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
668	            date = date.plusDays(1);
669	        }
670	        return date;
671	    }
672	
673	    private boolean isWeekend(LocalDate date) {
674	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
675	    }
676	
677	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
678	        return this.clinicService.findAllOwners().stream()
679	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
680	            .count();
681	    }
682	
683	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
684	    @Override
685	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
686	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
687	        if (currentOwner == null) {
688	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	        }
690	        currentOwner.setAddress(ownerFieldsDto.getAddress());
691	        currentOwner.setCity(ownerFieldsDto.getCity());
692	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
693	        currentOwner.setLastName(ownerFieldsDto.getLastName());
694	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
695	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
696	        this.clinicService.saveOwner(currentOwner);
697	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
698	    }
699	
700	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
701	    @Transactional
702	    @Override
703	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
704	        Owner owner = this.clinicService.findOwnerById(ownerId);
705	        if (owner == null) {
706	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
707	        }
708	        owner.setDeleted(true);
709	        this.clinicService.saveOwner(owner);
710	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
716	        Owner owner = this.clinicService.findOwnerById(ownerId);
717	        if (owner == null) {
718	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
719	        }
720	        HttpHeaders headers = new HttpHeaders();
721	        Pet pet = petMapper.toPet(petFieldsDto);
722	        owner.setId(ownerId);
723	        pet.setOwner(owner);
724	        pet.getType().setName(null);
725	        this.clinicService.savePet(pet);
726	        PetDto petDto = petMapper.toPetDto(pet);
727	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
728	            .buildAndExpand(pet.getId()).toUri());
729	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
730	    }
731	
732	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
733	    @Override
734	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
735	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
736	        if (currentOwner != null) {
737	            Pet currentPet = this.clinicService.findPetById(petId);
738	            if (currentPet != null) {
739	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
740	                currentPet.setName(petFieldsDto.getName());
741	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
742	                this.clinicService.savePet(currentPet);
743	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
744	            }
745	        }
746	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
747	    }
748	
749	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
750	    @Override
751	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
752	        HttpHeaders headers = new HttpHeaders();
753	        Visit visit = visitMapper.toVisit(visitFieldsDto);
754	        Pet pet = new Pet();
755	        pet.setId(petId);
756	        visit.setPet(pet);
757	        this.clinicService.saveVisit(visit);
758	        VisitDto visitDto = visitMapper.toVisitDto(visit);
759	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
760	            .buildAndExpand(visit.getId()).toUri());
761	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
762	    }
763	
764	
765	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
766	    @Override
767	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
768	        Owner owner = this.clinicService.findOwnerById(ownerId);
769	        if (owner != null) {
770	            Pet pet = owner.getPet(petId);
771	            if (pet != null) {
772	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
773	            }
774	        }
775	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	    }
777	}
